   122  static int MqttSocket_WriteDo(MqttClient *client, const byte* buf, int buf_len,
   123      int timeout_ms)
   124  {
   125      int rc;
   126
   127  #ifdef ENABLE_MQTT_TLS
   128      if (MqttClient_Flags(client,0,0) & MQTT_CLIENT_FLAG_IS_TLS) {
   129          client->tls.timeout_ms = timeout_ms;
   130          client->tls.sockRcWrite = 0; /* init value */
   131          rc = wolfSSL_write(client->tls.ssl, (char*)buf, buf_len);
   132          if (rc < 0) {
   133          #if defined(WOLFMQTT_DEBUG_SOCKET) || defined(WOLFSSL_ASYNC_CRYPT)
   134              int error = wolfSSL_get_error(client->tls.ssl, 0);
   135          #endif
   136          #ifdef WOLFMQTT_DEBUG_SOCKET
   137              if (error != WOLFSSL_ERROR_WANT_WRITE
   138              #ifdef WOLFSSL_ASYNC_CRYPT
   139                  && error != WC_PENDING_E
   140              #endif
   141              ) {
   142                  PRINTF("MqttSocket_WriteDo: SSL Error=%d (rc %d, sockrc %d)",
   143                      error, rc, client->tls.sockRcWrite);
   144              }
   145          #endif
   146
   147              /* return code from net callback */
   148              rc = client->tls.sockRcWrite;
   149          #ifdef WOLFSSL_ASYNC_CRYPT
   150              if (error == WC_PENDING_E) {
   151                  rc = MQTT_CODE_CONTINUE;
   152              }
   153          #endif
   154          }
   155      }
   156      else
   157  #endif /* ENABLE_MQTT_TLS */
   158      {
   159          rc = client->net->write(client->net->context, buf, buf_len,
   160              timeout_ms);
   161      }
   162
   163  #ifdef WOLFMQTT_DEBUG_SOCKET
   164      if (rc != 0 && rc != MQTT_CODE_CONTINUE) { /* hide in non-blocking case */
   165          PRINTF("MqttSocket_Write: Len=%d, Rc=%d", buf_len, rc);
   166      }
   167  #endif
   168
   169      return rc;
   170  }
