   172  int MqttSocket_Write(MqttClient *client, const byte* buf, int buf_len,
   173      int timeout_ms)
   174  {
   175      int rc;
   176
   177      /* Validate arguments */
   178      if (client == NULL || client->net == NULL || client->net->write == NULL ||
   179          buf == NULL || buf_len <= 0) {
   180          return MQTT_CODE_ERROR_BAD_ARG;
   181      }
   182
   183      /* check for buffer position overflow */
   184      if (client->write.pos >= buf_len) {
   185          return MQTT_TRACE_ERROR(MQTT_CODE_ERROR_OUT_OF_BUFFER);
   186      }
   187
   188  #ifdef WOLFMQTT_NONBLOCK
   189      rc = MqttSocket_WriteDo(client, &buf[client->write.pos],
   190          buf_len - client->write.pos, timeout_ms);
   191      if (rc >= 0) {
   192          client->write.pos += rc;
   193          client->write.total += rc;
   194          if (client->write.pos < buf_len) {
   195              rc = MQTT_CODE_CONTINUE;
   196          }
   197      }
   198      else if (rc == EWOULDBLOCK || rc == EAGAIN) {
   199          rc = MQTT_CODE_CONTINUE;
   200      }
   201
   202  #else
   203      do {
   204          rc = MqttSocket_WriteDo(client, &buf[client->write.pos],
   205              buf_len - client->write.pos, timeout_ms);
   206          if (rc <= 0) {
   207              break;
   208          }
   209          client->write.pos += rc;
   210          client->write.total += rc;
   211      } while (client->write.pos < buf_len);
   212  #endif /* WOLFMQTT_NONBLOCK */
   213
   214      /* handle return code */
   215      if (rc > 0) {
   216          /* return length write and reset position */
   217          rc = client->write.pos;
   218          client->write.pos = 0;
   219      }
   220
   221      return rc;
   222  }
