  1955  /* Read return code is length when > 0 */
  1956  int MqttPacket_Read(MqttClient *client, byte* rx_buf, int rx_buf_len,
  1957      int timeout_ms)
  1958  {
  1959      int rc, len, remain_read = 0;
  1960      MqttPacket* header = (MqttPacket*)rx_buf;
  1961
  1962      switch (client->packet.stat)
  1963      {
  1964          case MQTT_PK_BEGIN:
  1965          {
  1966              client->packet.header_len = MQTT_PACKET_HEADER_MIN_SIZE;
  1967              client->packet.remain_len = 0;
  1968
  1969              /* Read fix header portion */
  1970              rc = MqttSocket_Read(client, rx_buf, client->packet.header_len,
  1971                      timeout_ms);
  1972              if (rc < 0) {
  1973                  return MqttPacket_HandleNetError(client, rc);
  1974              }
  1975              else if (rc != client->packet.header_len) {
  1976                  return MqttPacket_HandleNetError(client,
  1977                           MQTT_TRACE_ERROR(MQTT_CODE_ERROR_NETWORK));
  1978              }
  1979          }
  1980          FALL_THROUGH;
  1981
  1982          case MQTT_PK_READ_HEAD:
  1983          {
  1984              int i;
  1985              client->packet.stat = MQTT_PK_READ_HEAD;
  1986
  1987              for (i = (client->packet.header_len - MQTT_PACKET_HEADER_MIN_SIZE);
  1988                   i < MQTT_PACKET_MAX_LEN_BYTES;
  1989                   i++) {
  1990                  /* Check if another byte is needed */
  1991                  if ((header->len[i] & MQTT_PACKET_LEN_ENCODE_MASK) == 0) {
  1992                      /* Variable byte length can be determined */
  1993                      break;
  1994                  }
  1995
  1996                  /* Read next byte and try decode again */
  1997                  len = 1;
  1998                  rc = MqttSocket_Read(client, &rx_buf[client->packet.header_len],
  1999                          len, timeout_ms);
  2000                  if (rc < 0) {
  2001                      return MqttPacket_HandleNetError(client, rc);
  2002                  }
  2003                  else if (rc != len) {
  2004                      return MqttPacket_HandleNetError(client,
  2005                               MQTT_TRACE_ERROR(MQTT_CODE_ERROR_NETWORK));
  2006                  }
  2007                  client->packet.header_len += len;
  2008              }
  2009
  2010              if (i == MQTT_PACKET_MAX_LEN_BYTES) {
  2011                  return MqttPacket_HandleNetError(client,
  2012                          MQTT_TRACE_ERROR(MQTT_CODE_ERROR_MALFORMED_DATA));
  2013              }
  2014
  2015              /* Try and decode remaining length */
  2016              rc = MqttDecode_Vbi(header->len,
  2017                      (word32*)&client->packet.remain_len,
  2018                      rx_buf_len - (client->packet.header_len - (i + 1)));
  2019              if (rc < 0) { /* Indicates error */
  2020                  return MqttPacket_HandleNetError(client, rc);
  2021              }
  2022              /* Indicates decode success and rc is len of header */
  2023              else {
  2024                  /* Add size of type and flags */
  2025                  rc += sizeof(header->type_flags);
  2026                  client->packet.header_len = rc;
  2027              }
  2028          }
  2029          FALL_THROUGH;
  2030
  2031          case MQTT_PK_READ:
  2032          {
  2033              /* read remainder of packet */
  2034              remain_read = client->packet.remain_len;
  2035              client->packet.stat = MQTT_PK_READ;
  2036
  2037              /* Make sure it does not overflow rx_buf */
  2038              if (rx_buf_len < client->packet.header_len) {
  2039                  return MQTT_TRACE_ERROR(MQTT_CODE_ERROR_OUT_OF_BUFFER);
  2040              }
  2041              if (remain_read > rx_buf_len - client->packet.header_len) {
  2042                  remain_read = rx_buf_len - client->packet.header_len;
  2043              }
  2044
  2045              /* Read remaining */

2045              /* Read remaining */
  2046              if (client->packet.remain_len > 0) {
  2047                  rc = MqttSocket_Read(client, &rx_buf[client->packet.header_len],
  2048                      remain_read, timeout_ms);
  2049                  if (rc <= 0) {
  2050                      return MqttPacket_HandleNetError(client, rc);
  2051                  }
  2052                  remain_read = rc;
  2053              }
  2054              break;
  2055          }
  2056      } /* switch (client->packet.stat) */
  2057
  2058      /* reset state */
  2059      client->packet.stat = MQTT_PK_BEGIN;
  2060
  2061      /* Return read length */
  2062      return client->packet.header_len + remain_read;
  2063  }
